def resize_image(img_path, width=224, height=224, mode='pad'):
    with Image.open(img_path) as img:
        if mode == 'stretch':
            resized = img.resize((224, 224), Image.Resampling.LANCZOS)
        elif mode == 'pad':
            resized = ImageOps.pad(img, (224, 224), Image.Resampling.LANCZOS)
        elif mode == 'crop':
            resized = ImageOps.fit(img, (224, 224), Image.Resampling.LANCZOS)
